import{_ as o,o as e,c as a,a2 as u}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"1984年 · 回购与估值之道","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1984年.md","filePath":"05_quotes/by-year/1984年.md"}'),q={name:"05_quotes/by-year/1984年.md"};function l(r,t,c,p,s,_){return e(),a("div",null,[...t[0]||(t[0]=[u('<h1 id="_1984年-·-回购与估值之道" tabindex="-1">1984年 · 回购与估值之道 <a class="header-anchor" href="#_1984年-·-回购与估值之道" aria-label="Permalink to &quot;1984年 · 回购与估值之道&quot;">​</a></h1><blockquote><p>&quot;当优秀企业股价远低于内在价值，回购对不卖的股东太有利了：一块钱投入买到两块钱现值，企业收购几乎做不到。&quot;——巴菲特（54岁）</p></blockquote><p>本页收录1984年致股东信中的经典语录。巴菲特在这一年系统阐述了回购的本质逻辑，并警示了保险业损失准备金的&quot;租西装&quot;陷阱。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;当优秀企业股价远低于内在价值，管理层回购，说明它站在股东这边，不是扩张管理版图，不伤害股东利益。看到这点，股东和潜在股东都会对未来回报预期更高，股价就会更接近内在价值。&quot;</p></blockquote><blockquote><p>&quot;基本算术，内在价值每股远低于市价大额回购，立刻就能大幅提升每股价值。公司收购项目几乎从来做不到一块钱投入拿两块钱现值，回购做得到。&quot;</p></blockquote><blockquote><p>&quot;好公司回购，就是证明管理层站在股东这边，不是嘴说没用，行动才是关键，久了市场肯定知道。&quot;</p></blockquote><blockquote><p>&quot;绿票讹诈交易里，两方个人得益，都是剥削无辜没参与第三方。玩家：(1) &#39;股东&#39;勒索者，股票证书墨迹还没干，就给管理层发最后通牒，要钱还是要命；(2) 内部人，不管谁出钱赶紧求和，只要钱不是自己出；(3) 股东，钱被用来打发勒索者。&quot;</p></blockquote><blockquote><p>&quot;很多企业经理明明知道再投资回报率低，还是留存，这种情况很多，因为惯性，他们喜欢扩张帝国。母公司CEO让子公司A分掉所有盈利，投到子公司B赚更高回报，这逻辑完全对，但母公司层面经理常常做不到。&quot;</p></blockquote><blockquote><p>&quot;受限盈利对所有者很少有价值，实际上，哪怕未来分红，也经常要打很大折扣。通胀逼的，一美元留存变成25美分市场价值，就像十年前联合爱迪生那样。&quot;</p></blockquote><blockquote><p>&quot;不是所有盈利都一样，很多企业特别是高资产/利润比，通胀让很多报告盈利变成&#39;假&#39;，这些假盈利就是&#39;受限&#39;盈利，不能分。&quot;</p></blockquote><blockquote><p>&quot;只有当留存一美元预期能创造至少一美元市场价值，才应该留存。&quot;</p></blockquote><blockquote><p>&quot;如果长期无风险利率是15%，你留存一块钱只能赚10%，那你就应该分掉，让股东自己去买15%的，你拿着干嘛？&quot;</p></blockquote><blockquote><p>&quot;用商人视角看债券，能避免很多大错。1946年，20年期AAA免税债券收益率不到1%，投资者买的时候，就是买一个每年赚1%的生意，永远没法更高，一眼就能看出这破生意不能买。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1984年伯克希尔净值增长1.526亿美元，过去二十年账面价值复利增长22.1%。巴菲特在这封信中明确表示历史22%的回报率已成过去，未来十年要维持15%复利需要总共赚39亿美元，&quot;需要几个大想法，小想法不行&quot;。GEICO和通用食品的比例赎回争议、会计处理分歧，以及对绿票讹诈的严厉批判，是本年重要注脚。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1984年/翻译.html">01_letters/1984年/翻译</a> · <a href="/01_letters/1984年/核心总结.html">01_letters/1984年/核心总结</a> · <a href="/01_letters/1984年/思维导图.html">01_letters/1984年/思维导图</a></p>',21)])])}const k=o(q,[["render",l]]);export{h as __pageData,k as default};
